    @Test
    void updateRejectsFrameIdInRequestBody() throws Exception {
        create(createRequest(
            "immutable", "LIVE", "DIGITAL", "UNDERGROUND", "D6", "London", "Station", "Address"
        ));

        mockMvc.perform(put("/api/frames/{frameId}", "immutable")
