        mockMvc.perform(get("/api/frames/{frameId}", "replace-me"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.statusReason").value("Maintenance"))
            .andExpect(jsonPath("$.site.siteNumber").value("SITE-2"));
    }

